node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update the booking
const stmt = db.prepare(\`
  UPDATE flight_bookings 
  SET cabin_class = 'economy',
      price_paid = 520,
      fare_difference = -660,
      refund_amount = 660,
      payment_history_json = ?
  WHERE booking_id = 'BK-B70889'
\`);

const paymentHistory = JSON.stringify([
  { payment_id: 'cc_b3676891', amount: 1180, type: 'original_payment' },
  { payment_id: 'cc_b3676891', amount: -660, type: 'cabin_downgrade_refund' }
]);

const result = stmt.run(paymentHistory);
console.log('Rows updated:', result.changes);

// Verify the updated booking
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'BK-B70889'\").get();
console.log('\n=== Updated Booking ===');
console.log(JSON.stringify(booking, null, 2));
"
